function update(dt) {
  if (phase !== 'playing') return;
  // Player physics (existing)
  if (keys.has(' ') ) {
    player.vx += 200 * dt;
  }
  player.x += player.vx * dt;
  player.y += player.vy * dt;
  player.vx *= 0.99;
  player.vy *= 0.99;
  if (player.x < 0) { player.x = 0; player.vx = Math.abs(player.vx); }
  if (player.x > canvas.width) { player.x = canvas.width; player.vx = -Math.abs(player.vx); }
  if (player.y < 0) { player.y = 0; player.vy = Math.abs(player.vy); }
  if (player.y > canvas.height) { player.y = canvas.height; player.vy = -Math.abs(player.vy); }

  // Hazard spawn timing
  spawnTimer += dt;
  if (spawnTimer >= SPAWN_INTERVAL) {
    spawnTimer -= SPAWN_INTERVAL;
    // ensure safe distance
    let tries = 0;
    while (tries < 5) {
      const side = Math.random() < 0.5 ? 'top' : 'bottom';
      const x = Math.random() * canvas.width;
      const y = side === 'top' ? -20 : canvas.height + 20;
      const dy = side === 'top' ? HAZARD_SPEED : -HAZARD_SPEED;
      const dx = (Math.random() - 0.5) * 50;
      const dist = Math.hypot(x - player.x, (y < 0 ? 0 : canvas.height) - player.y);
      if (dist > SAFE_RADIUS) { hazards.push({ x, y, vx: dx, vy: dy }); break; }
      tries++;
    }
  }

  // Update hazards
  for (let i = hazards.length - 1; i >= 0; i--) {
    const h = hazards[i];
    h.x += h.vx * dt;
    h.y += h.vy * dt;
    // remove offscreen
    if (h.y < -30 || h.y > canvas.height + 30) { hazards.splice(i, 1); continue; }
    // collision with player
    const d = Math.hypot(h.x - player.x, h.y - player.y);
    if (d < PLAYER_R + HAZARD_R) {
      phase = 'gameover';
      // stop loop by not calling further updates
    }
  }

